import type {
  DocumentSnapshot,
  FileEntry,
  SaveDocumentRequest,
  SaveResult,
  SearchResult,
  WorkspaceDescriptor,
  WatchEvent,
} from "../../contracts/types";

/** Thin IPC façade — in browser/dev uses mock; under Tauri uses invoke. */
export function isTauriRuntime(): boolean {
  if (typeof window === "undefined") return false;
  const w = window as Window & {
    __TAURI_INTERNALS__?: unknown;
    __TAURI__?: unknown;
    isTauri?: boolean;
  };
  return Boolean(w.__TAURI_INTERNALS__ || w.__TAURI__ || w.isTauri);
}

async function invoke<T>(cmd: string, args?: Record<string, unknown>): Promise<T> {
  if (!isTauriRuntime()) {
    return mockInvoke<T>(cmd, args);
  }
  const { invoke: tauriInvoke } = await import("@tauri-apps/api/core");
  return tauriInvoke<T>(cmd, args);
}

export const ipc = {
  openWorkspace: (path: string) => invoke<WorkspaceDescriptor>("open_workspace", { path }),
  listEntries: (workspaceId: string, relativePath: string) =>
    invoke<FileEntry[]>("list_entries", { workspaceId, relativePath }),
  readDocument: (workspaceId: string, path: string) =>
    invoke<DocumentSnapshot>("read_document", { workspaceId, path }),
  saveDocument: (req: SaveDocumentRequest) => invoke<SaveResult>("save_document", { req }),
  searchWorkspace: (workspaceId: string, query: string) =>
    invoke<SearchResult[]>("search_workspace", { workspaceId, query }),
  exportHtml: (workspaceId: string, path: string, destination: string) =>
    invoke<void>("export_html", { workspaceId, path, destination }),
};

/** Native open dialogs (folder / markdown file). Returns absolute path or null. */
export async function pickFolder(): Promise<string | null> {
  if (!isTauriRuntime()) {
    return mockPick("folder");
  }
  const { open } = await import("@tauri-apps/plugin-dialog");
  const selected = await open({
    directory: true,
    multiple: false,
    title: "Abrir pasta do workspace",
  });
  return typeof selected === "string" ? selected : null;
}

export async function pickMarkdownFile(): Promise<string | null> {
  if (!isTauriRuntime()) {
    return mockPick("file");
  }
  const { open } = await import("@tauri-apps/plugin-dialog");
  const selected = await open({
    multiple: false,
    title: "Abrir arquivo Markdown",
    filters: [{ name: "Markdown", extensions: ["md", "markdown", "mdx"] }],
  });
  return typeof selected === "string" ? selected : null;
}

// --- Browser mock -----------------------------------------------------------

const mockDocs = new Map<string, { content: string; hash: string }>();
let mockWorkspaceLabel = "demo-workspace";

const DEMO_FILES: FileEntry[] = [
  { name: "README.md", relativePath: "README.md", kind: "file", size: 120 },
  { name: "notas.md", relativePath: "notas.md", kind: "file", size: 80 },
  { name: "guia.md", relativePath: "docs/guia.md", kind: "file", size: 200 },
];

const DEMO_CONTENT: Record<string, string> = {
  "README.md": `# MD Studio

Editor Markdown **local** e seguro.

## Começar

1. Use **Abrir pasta** ou **Abrir arquivo** (no app Tauri).
2. Edite no painel central.
3. Salve com **Ctrl+S**.

> [!NOTE]
> No browser (\`pnpm dev\`) o filesystem é simulado.
`,
  "notas.md": `# Notas

- Item um
- Item dois

\`\`\`ts
const hello = "world";
\`\`\`
`,
  "docs/guia.md": `# Guia

## Preview

O preview atualiza com debounce.

## Matemática

Inline $x^2$ e bloco:

$$
\\sum_{i=1}^{n} i = \\frac{n(n+1)}{2}
$$
`,
};

function hash(s: string): string {
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (Math.imul(31, h) + s.charCodeAt(i)) | 0;
  return `h${(h >>> 0).toString(16)}`;
}

function mockPick(kind: "folder" | "file"): string {
  // Simulated paths for browser UX
  return kind === "folder" ? "/demo/workspace" : "/demo/workspace/README.md";
}

async function mockInvoke<T>(cmd: string, args?: Record<string, unknown>): Promise<T> {
  if (cmd === "open_workspace") {
    const path = String(args?.path ?? ".");
    mockWorkspaceLabel = path.split("/").filter(Boolean).pop() || "workspace";
    return {
      id: "ws-mock",
      rootLabel: mockWorkspaceLabel,
      kind: path.endsWith(".md") ? "single-file" : "folder",
    } as T;
  }
  if (cmd === "list_entries") {
    return DEMO_FILES as T;
  }
  if (cmd === "read_document") {
    const path = String(args?.path ?? "README.md");
    const content =
      mockDocs.get(path)?.content ?? DEMO_CONTENT[path] ?? `# ${path}\n\nDocumento demo.\n`;
    const contentHash = hash(content);
    mockDocs.set(path, { content, hash: contentHash });
    return {
      workspaceId: String(args?.workspaceId ?? "ws-mock"),
      relativePath: path,
      content,
      encoding: "utf-8",
      mtimeMs: Date.now(),
      contentHash,
      version: 1,
    } as T;
  }
  if (cmd === "save_document") {
    const req = args?.req as SaveDocumentRequest;
    const prev = mockDocs.get(req.relativePath);
    if (prev && prev.hash !== req.expectedHash) {
      return { ok: false, code: "HashMismatch", message: "Arquivo alterado no disco" } as T;
    }
    const contentHash = hash(req.content);
    mockDocs.set(req.relativePath, { content: req.content, hash: contentHash });
    return {
      ok: true,
      snapshot: {
        workspaceId: req.workspaceId,
        relativePath: req.relativePath,
        content: req.content,
        encoding: "utf-8",
        mtimeMs: Date.now(),
        contentHash,
        version: 2,
      },
    } as T;
  }
  if (cmd === "search_workspace") {
    const q = String(args?.query ?? "").toLowerCase();
    if (!q) return [] as T;
    const results: SearchResult[] = [];
    for (const [path, body] of Object.entries(DEMO_CONTENT)) {
      body.split("\n").forEach((line, i) => {
        if (line.toLowerCase().includes(q)) {
          results.push({ relativePath: path, line: i + 1, preview: line.slice(0, 120) });
        }
      });
    }
    return results as T;
  }
  if (cmd === "export_html") return undefined as T;
  throw new Error(`mock missing: ${cmd}`);
}

export type { WatchEvent };
